    read(s, p) { const F = E.flat(p.v, p.r, fmu(p), p.m); return [[T('road μ', 'μ الطريق'), f(fmu(p), 2)], [T('maximum speed √(μgr)', 'السرعة القصوى'), f(F.vMax, 2) + ' m/s (' + f(F.vMax * 3.6, 0) + ' km/h)'], [T('your speed', 'سرعتك'), f(p.v, 1) + ' m/s (' + f(p.v * 3.6, 0) + ' km/h)'], [T('friction needed m v²/r', 'الاحتكاك المطلوب'), f(F.Fc, 0) + ' N'], [T('friction available μmg', 'المتاح'), f(F.fmax, 0) + ' N'], [T('μ needed v²/(rg)', 'μ المطلوب'), f(F.need, 3)], [T('path radius', 'نصف قطر المسار'), F.grips ? f(p.r, 1) + ' m' : f(F.rho, 1) + ' m (' + T('wider: sliding', 'أوسع: انزلاق') + ')'], [T('distance from centre', 'البعد عن المركز'), f(s.d, 2) + ' m']]; },
