      W.sat = new THREE.Group(); const body = M.rbox(0.28, 0.28, 0.4, 0.03, M.mat(0xd8a93a, { metalness: 1, roughness: 0.35 })); W.sat.add(body); [-1, 1].forEach(sg0 => { const pn = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.02, 0.3), M.mat(0x1b3a8a, { metalness: 0.6, roughness: 0.25, clearcoat: 1 })); pn.position.x = sg0 * 0.58; W.sat.add(pn); });
      const dish = new THREE.Mesh(new THREE.SphereGeometry(0.12, 20, 10, 0, TAU, 0, PI / 2.6), M.mat(0xeeeeee, { side: THREE.DoubleSide, metalness: 0.5 })); dish.position.z = -0.24; dish.rotation.x = -PI / 2; W.sat.add(dish); S.scene.add(W.sat);
