    formulas(s, p) { const o = orb(p), GM = E.G * o.M; return [`G M m / r² = m v² / r ⇒ v = √(GM/r) = √(${K.fmt(GM / 1e14, 4)}×10¹⁴ / ${K.fmt(o.r / 1e6, 4)}×10⁶) = ${B(f(o.v, 0) + ' m/s')}`, `T = 2π r / v = 2π √(r³/GM) = ${B(hm(o.T))}`, `T² / r³ = 4π² / GM = ${B(K.fmt(4 * PI * PI / GM * 1e14, 4) + ' × 10⁻¹⁴ s²/m³')} (${T('same for every orbit of this planet', 'ثابت لكل مدار')})`, `${T('launch', 'الإطلاق')} = ${f(p.k, 2)} × v<sub>circ</sub>${p.k >= Math.SQRT2 - 1e-9 ? ' ≥ √2 → ' + T('escape', 'إفلات') : ''}`]; },
    why: (s, p) => (s.crashed ? T('Too slow: the path dipped into the planet.', 'أبطأ: اصطدم.') : s.escaped ? T('At √2 × the circular speed or more the satellite has escape speed: it never comes back.', 'سرعة الإفلات.') : Math.abs(p.k - 1) < 0.005 ? T('Gravity is the **only** force and it points at the planet’s centre: it is exactly the m v²/r needed. The satellite is falling all the time — but sideways fast enough to keep missing.', 'الجاذبية هي القوة المركزية.') : T('Not at the circular speed: gravity no longer equals m v²/r at the start, so the distance changes — the orbit is an ellipse.', 'ليس بالسرعة الدائرية: قطع ناقص.')),
