    observe(s, p) { const c = E.chair(p.d, p.L, p.w, p.m); return { text: `At ω = ${f(p.w, 2)} rad/s the chains settle at ${f(c.deg, 1)}°, for any rider mass (here ${p.m} kg).`, predOk: i => i === 2 }; },
